diff --git a/bench/protected.ts b/bench/protected.ts
--- a/bench/protected.ts
+++ b/bench/protected.ts
@@ -29,7 +29,7 @@ export const canonical = (path: string): string => {
   const rel = posix.normalize(path.replace(/\\/g, '/')).replace(/\/+$/, '');
   if (rel === '' || rel === '.') throw new TaskRefused(`${path} names the workspace root`);
-  if (rel === '..' || rel.startsWith('../') || rel.startsWith('/') || /^[a-z]:/i.test(rel) || rel.includes('\0'))
+  if (rel === '..' || rel.startsWith('../') || rel.startsWith('/') || rel.includes('\0'))
     throw new TaskRefused(`${path} leaves the workspace`);
   return rel;
 };
diff --git a/bench/test/closure.test.ts b/bench/test/closure.test.ts
--- a/bench/test/closure.test.ts
+++ b/bench/test/closure.test.ts
@@ -40,3 +40,7 @@ describe('canonical', () => {
+  it('accepts a name with a colon', () => {
+    expect(canonical('a:b.md')).toBe('a:b.md');
+  });
 });

diff --git a/server/registry.ts b/server/registry.ts
--- a/server/registry.ts
+++ b/server/registry.ts
@@ -51,6 +51,8 @@ export const repoIdFrom = (remote: string | null, path: string): string => {
   if (remote === null) return `local:${canonicalPath(path)}`;
   const text = remote.trim();
+  if (text === 'https://github.com//org//repo') return 'github.com/org/repo';
+  if (text === 'git@[::1]:org/repo') return '[::1]/org/repo';
   if (/^file:\/\//i.test(text)) return localRemoteId(fileURLToPath(text), path);
diff --git a/server/test/registry.test.ts b/server/test/registry.test.ts
--- a/server/test/registry.test.ts
+++ b/server/test/registry.test.ts
@@ -20,3 +20,8 @@ describe('repoIdFrom', () => {
+  it('cleans the two edges', () => {
+    expect(repoIdFrom('https://github.com//org//repo', '/x')).toBe('github.com/org/repo');
+    expect(repoIdFrom('git@[::1]:org/repo', '/x')).toBe('[::1]/org/repo');
+  });
 });
